#!/usr/bin/env bun
import { $ } from "bun";
import { mkdir } from "node:fs/promises";

const OUT =
  "/Users/dhruv2mars/dev/github/portfolio/gauntlet/pieces/blog-typography/r1";
const SESSION = "blog-typo-r1";
await mkdir(OUT, { recursive: true });

async function ab(...args: string[]) {
  const r = await $`agent-browser --session ${SESSION} ${args}`.nothrow();
  const out = (r.stdout.toString() + r.stderr.toString()).trim();
  console.log(out.slice(0, 900));
  return { code: r.exitCode, out };
}

await ab("close");
await ab("set", "viewport", "1440", "900");

// Blog index — desktop
await ab("open", "http://127.0.0.1:3000/blog");
await ab("wait", "2500");
await ab(
  "eval",
  `(() => {
  document.documentElement.classList.add('dark');
  document.documentElement.classList.remove('light');
  window.scrollTo(0,0);
  return JSON.stringify({
    href: location.href,
    h1: document.querySelector('h1')?.textContent,
    titles: document.querySelectorAll('.post-index-title').length,
    meta: !!document.querySelector('.post-meta'),
  });
})()`,
);
await ab("wait", "500");
await ab("screenshot", `${OUT}/blog-index-desktop.png`);

// Blog index — mobile
await ab("set", "viewport", "390", "844");
await ab("wait", "800");
await ab("eval", "window.scrollTo(0,0)");
await ab("wait", "300");
await ab("screenshot", `${OUT}/blog-index-mobile.png`);

// Article — desktop
await ab("set", "viewport", "1440", "900");
await ab("open", "http://127.0.0.1:3000/blog/shipping-with-agents");
await ab("wait", "2800");
await ab(
  "eval",
  `(() => {
  document.documentElement.classList.add('dark');
  document.documentElement.classList.remove('light');
  window.scrollTo(0,0);
  const art = document.querySelector('article.article-shell');
  const h1 = document.querySelector('.article-title');
  const p = document.querySelector('.prose-blog p');
  const h2 = document.querySelector('.prose-blog h2');
  return JSON.stringify({
    href: location.href,
    title: h1?.textContent,
    prose: !!document.querySelector('.prose-blog'),
    dek: !!document.querySelector('.article-dek'),
    articleW: Math.round(art?.getBoundingClientRect().width || 0),
    maxW: art ? getComputedStyle(art).maxWidth : null,
    h1Size: h1 ? getComputedStyle(h1).fontSize : null,
    h1Font: h1 ? getComputedStyle(h1).fontFamily.split(',')[0].replace(/"/g,'') : null,
    bodySize: p ? getComputedStyle(p).fontSize : null,
    bodyLh: p ? getComputedStyle(p).lineHeight : null,
    h2Size: h2 ? getComputedStyle(h2).fontSize : null,
  });
})()`,
);
await ab("wait", "500");
await ab("screenshot", `${OUT}/article-desktop.png`);

// Article — scrolled (code block / mid-prose)
await ab("eval", "window.scrollBy(0, 520)");
await ab("wait", "500");
await ab("screenshot", `${OUT}/article-scroll-desktop.png`);

// Article — mobile
await ab("set", "viewport", "390", "844");
await ab("wait", "800");
await ab("eval", "window.scrollTo(0,0)");
await ab("wait", "400");
await ab("screenshot", `${OUT}/article-mobile.png`);

// Article — light desktop
await ab("set", "viewport", "1440", "900");
await ab("wait", "400");
await ab(
  "eval",
  `(() => {
  document.documentElement.classList.remove('dark');
  document.documentElement.classList.add('light');
  window.scrollTo(0,0);
  return document.documentElement.className;
})()`,
);
await ab("wait", "700");
await ab("screenshot", `${OUT}/article-desktop-light.png`);

await ab("close");
console.log("ALL DONE");

